def _get_trust_presentation_sync_history(
    self, tenant: str, query: str
) -> None:
    # GET /v1/trust/presentation-sync/history：只读查询某同步来源
    # （签名方）已落盘的外部演示消费事件在指定时点的历史页。
    # 查询参数仅允许 signer_did、at、limit、after 且均只能出现
    # 一次：signer_did 必填非空；at 缺省取该来源同步检查点
    # next_after、须为 ASCII 非负整数；limit 缺省 50、限 1..200；
    # after 缺省 0、须为 ASCII 非负整数。空值、重复、未知参数、
    # 非 ASCII 数字、符号、越界或 after>at 均 400 且仅
    # {"error":"请求非法"}；该来源未同步（含跨租户）404 仅
    # {"error":"同步来源不存在"}，at 超过检查点 409 仅
    # {"error":"同步游标冲突"}。200 键序恰为 signer_did、at、
    # events、next_after；以请求初原子快照取 cursor<=at 的事件，
    # 再按 cursor>after 升序取前 limit 项，事件键序恰为 cursor、
    # consumption_id、issuer_did、presentation_id、consumed_at
    # （cursor 为正整数，其余四值为非空字符串，consumed_at 为
    # UTC 秒精度 Z）；空页 next_after 等于 after，否则等于末项
    # cursor。同一 at 的分页不受后续同步影响，重启逐字节一致。
    # 纯只读：不推进检查点、不改判重索引、不记审计、不触发落盘。
    try:
        params = parse_qs(query, keep_blank_values=True)
        allowed = {"signer_did", "at", "limit", "after"}
        if set(params) - allowed:
            raise ValidationError("请求非法")

        def _single(name: str) -> Optional[str]:
            values = params.get(name)
            if values is None:
                return None
            if len(values) != 1:
                raise ValidationError("请求非法")
            return values[0]

        signer_did = _single("signer_did")
        if signer_did is None or not signer_did:
            raise ValidationError("请求非法")

        at_raw = _single("at")
        at = (
            _parse_nonneg_int(at_raw, "at")
            if at_raw is not None
            else None
        )

        limit_raw = _single("limit")
        if limit_raw is not None:
            limit = _parse_nonneg_int(limit_raw, "limit")
            if not 1 <= limit <= 200:
                raise ValidationError("请求非法")
        else:
            limit = 50

        after_raw = _single("after")
        if after_raw is not None:
            after = _parse_nonneg_int(after_raw, "after")
        else:
            after = 0

        if at is not None and after > at:
            raise ValidationError("请求非法")
    except ValidationError:
        raise ValidationError("请求非法")

    try:
        at_value, events, next_after = (
            store.list_trust_presentation_sync_history(
                tenant, signer_did, at, after, limit
            )
        )
    except ValidationError:
        # at 缺省时取检查点：after 超过生效 at 同样为请求非法。
        raise ValidationError("请求非法")
    self._send_json(
        200,
        {
            "signer_did": signer_did,
            "at": at_value,
            "events": events,
            "next_after": next_after,
        },
    )

def _get_trust_presentation_sync_receipt(
    self, tenant: str, query: str
) -> None:
    # GET /v1/trust/presentation-sync/receipt：演示消费同步进度
    # 签名回执（纯只读）。
    # 查询参数仅允许 signer_did、verifier_did、nonce 且均只能
    # 出现一次：三者均须为非空字符串，nonce 长度限 1..256 个
    # Unicode 码点。缺失、重复、空值或未知参数一律 400 且仅
    # {"error":"请求非法"}。
    # 同步来源（signer_did）或验证者 DID 不存在（含跨租户）
    # 404 仅 {"error":"资源不存在"}；验证者已停用 409 仅
    # {"error":"验证者已停用"}。
    # 原子读取该来源检查点及 cursor<=next_after 的事件，200
    # 顶层键序恰为 receipt、signature；receipt 键序恰为
    # signer_did、next_after、digest、verifier_did、
    # verifier_key_version、nonce。事件按 cursor 升序，逐行
    # 沿用既有 history 五键与 NDJSON 编码（UTF-8 紧凑 JSON、
    # 非 ASCII 不转义、LF 结行），digest 为行字节的 SHA-256
    # 小写 64 位 hex；signature 由验证者当前私钥对 receipt 按
    # 既有规范化 JSON 与 ES256 裸 R||S 无填充 base64url 协议
    # 生成。不推进检查点、不写状态或审计；重启后 receipt 与
    # digest 相同且签名可验。
    try:
        params = parse_qs(query, keep_blank_values=True)
        allowed = {"signer_did", "verifier_did", "nonce"}
        if set(params) - allowed:
            raise ValidationError("请求非法")

        def _single(name: str) -> Optional[str]:
            values = params.get(name)
            if values is None:
                return None
            if len(values) != 1:
                raise ValidationError("请求非法")
            return values[0]

        signer_did = _single("signer_did")
        if signer_did is None or not signer_did:
            raise ValidationError("请求非法")
        verifier_did = _single("verifier_did")
        if verifier_did is None or not verifier_did:
            raise ValidationError("请求非法")
        nonce = _single("nonce")
        if nonce is None or not nonce:
            raise ValidationError("请求非法")
        if not 1 <= len(nonce) <= 256:
            raise ValidationError("请求非法")
    except ValidationError:
        raise ValidationError("请求非法")

    (
        next_after,
        events,
        verifier_key_version,
        verifier_private_pem,
    ) = store.get_presentation_sync_receipt_material(
        tenant, signer_did, verifier_did
    )

    digest = hashlib.sha256(
        _presentation_consumption_ndjson_bytes(events)
    ).hexdigest()
    receipt = {
        "signer_did": signer_did,
        "next_after": next_after,
        "digest": digest,
        "verifier_did": verifier_did,
        "verifier_key_version": verifier_key_version,
        "nonce": nonce,
    }
    signature = crypto.sign(receipt, verifier_private_pem)
    self._send_json(200, {"receipt": receipt, "signature": signature})

def _get_trust_anchor_snapshot(self, tenant: str, query: str) -> None:
    # GET /v1/trust/anchors/snapshot?signer_did=：对本租户全部
    # 信任锚点生成签名快照。查询参数仅允许唯一非空 signer_did，
    # 缺失/空值/重复/未知参数一律 400 且仅 {"error"}；签名 DID
    # 未知（含他租户）404、已停用 409。200 键序 anchors、
    # signer_did、signer_key_version、signature；anchors 原子
    # 取本租户锚点并按 did 码点、key_version 升序，项键序 did、
    # key_version、public_key、status、updated_at、uses（类型
    # 沿用既有锚点与用途响应）；signature 由签名 DID 当前私钥
    # 对前三键递归键升序紧凑 UTF-8 JSON 做 ES256 裸 R||S 无填
    # 充 base64url 签名。纯只读：不写状态、不记审计。
    params = parse_qs(query, keep_blank_values=True)
    unknown = sorted(set(params) - {"signer_did"})
    if unknown:
        raise ValidationError(
            f"不支持的查询参数: {', '.join(unknown)}"
        )
    signer_values = params.get("signer_did")
    if signer_values is None:
        raise ValidationError("查询参数 signer_did 必填")
    if len(signer_values) != 1:
        raise ValidationError("查询参数 signer_did 只能提供一次")
    signer_did = signer_values[0]
    if not signer_did:
        raise ValidationError(
            "查询参数 signer_did 必须为非空字符串"
        )

    key_version, private_pem = (
        store.get_trust_anchor_snapshot_signer(tenant, signer_did)
    )
    anchors = store.list_trust_anchor_snapshot(tenant)
    signed = {
        "anchors": anchors,
        "signer_did": signer_did,
        "signer_key_version": key_version,
    }
    signature = crypto.sign(signed, private_pem)
    snapshot = dict(signed)
    snapshot["signature"] = signature
    self._send_json(200, snapshot)

def _anchor_snapshot_is_well_formed(self, snapshot: Any) -> bool:
    # 快照结构校验（“快照非法”）：恰含四键且各键类型/取值合法。
    if not isinstance(snapshot, dict):
        return False
    if set(snapshot) != {
        "anchors",
        "signer_did",
        "signer_key_version",
        "signature",
    }:
        return False
    anchors = snapshot["anchors"]
    if not isinstance(anchors, list):
        return False
    for item in anchors:
        if not isinstance(item, dict):
            return False
        if set(item) != {
            "did",
            "key_version",
            "public_key",
            "status",
            "updated_at",
            "uses",
        }:
            return False
        if not isinstance(item["did"], str) or not item["did"]:
            return False
        key_version = item["key_version"]
        if (
            not isinstance(key_version, int)
            or isinstance(key_version, bool)
            or key_version < 1
        ):
            return False
        if (
            not isinstance(item["public_key"], str)
            or not item["public_key"]
        ):
            return False
        if item["status"] not in ("active", "revoked"):
            return False
        updated_at = item["updated_at"]
        if updated_at is not None and not isinstance(
            updated_at, str
        ):
            return False
        uses = item["uses"]
        if not isinstance(uses, list) or not uses:
            return False

