    self, data: Dict[str, Any], fields: Tuple[str, ...]
) -> None:
    for field in fields:
        if field not in data:
            raise ValidationError(f"缺少字段: {field}")
        value = data[field]
        if not isinstance(value, str) or not value:
            raise ValidationError(
                f"字段 {field} 必须为非空字符串"
            )

